332	/**
333	 * Get the current drift trend summary.
334	 */
335	export async function getDriftTrendSummary(): Promise<{
336	  currentScore: number | null;
337	  trend: string;
338	  weekOverWeekDelta: number | null;
339	  snapshotsCount: number;
340	  avgScore7d: number | null;
341	  avgScore30d: number | null;
342	}> {
343	  const db = await getDb();
344	  if (!db) return {
345	    currentScore: null,
346	    trend: 'unknown',
347	    weekOverWeekDelta: null,
348	    snapshotsCount: 0,
349	    avgScore7d: null,
350	    avgScore30d: null,
351	  };
352	  const latest = await db.select()
353	    .from(truthDriftTimeSeries)
354	    .orderBy(desc(truthDriftTimeSeries.capturedAt))
355	    .limit(1);
356	  
357	  if (latest.length === 0) {
358	    return {
359	      currentScore: null,
360	      trend: 'unknown',
361	      weekOverWeekDelta: null,
362	      snapshotsCount: 0,
363	      avgScore7d: null,
364	      avgScore30d: null,
365	    };
366	  }
367	  
368	  // Count total snapshots
369	  const countResult = await db.select({ count: sql<number>`count(*)` })
370	    .from(truthDriftTimeSeries);
371	  
372	  // Get 7-day average
373	  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
374	  const avg7d = await db.select({ avg: sql<number>`AVG(${truthDriftTimeSeries.truthDriftScore})` })
375	    .from(truthDriftTimeSeries)
376	    .where(sql`${truthDriftTimeSeries.capturedAt} >= ${sevenDaysAgo}`);
377	  
378	  // Get 30-day average
379	  const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
380	  const avg30d = await db.select({ avg: sql<number>`AVG(${truthDriftTimeSeries.truthDriftScore})` })
381	    .from(truthDriftTimeSeries)
382	    .where(sql`${truthDriftTimeSeries.capturedAt} >= ${thirtyDaysAgo}`);
383	  
384	  return {
385	    currentScore: latest[0].truthDriftScore,
386	    trend: latest[0].trend || 'stable',
387	    weekOverWeekDelta: latest[0].weekOverWeekDelta,
388	    snapshotsCount: countResult[0]?.count || 0,
389	    avgScore7d: avg7d[0]?.avg ? Math.round(avg7d[0].avg) : null,
390	    avgScore30d: avg30d[0]?.avg ? Math.round(avg30d[0].avg) : null,
391	  };
392	}
