/**
 * Governed Generate SDK — Full Inline Governance Enforcement
 * 
 * This is the canonical entry point for any LLM generation that must pass
 * through Gravito governance. It wraps the full pipeline:
 * 
 *   1. Auto-register the calling product (if external)
 *   2. Pre-generation: classify content, inject governance context
 *   3. LLM generation via safeLLM (never-throw wrapper)
 *   4. Post-generation: heuristic analysis → Gravito inline review → decision
 *   5. Verdict enforcement: pass / stabilize / block / regenerate
 *   6. Failsafe: if Gravito is down, use degraded-mode policy engine
 * 
 * Usage:
 *   const result = await governedGenerate({
 *     messages: [{ role: 'user', content: 'Write a health disclaimer' }],
 *     productId: 'troubadour-music-app',
 *     contentType: 'medical',
 *     contentRole: 'user-facing',
 *   });
 */
import { safeLLM, isFallbackResponse } from './safe-llm';
import { coProcessorPreGenerate, coProcessorPostGenerate, applyVerdict, type ContentDomain, type CoProcessorVerdict, type CoProcessorDecision } from './co-processor/index';
import { registerSurfaceIfMissing, incrementActivityCounter } from './auto-surface-registration';
import { evaluateDegradedPolicy, recordDegradedEvaluation } from './degraded-policy-engine';
import { resolveGovernanceContext, buildGovernanceInjection, recordContextResolution } from './product-context';
import { createLogger } from '../_core/logger';
import { getGovernanceBypassState, withGovernanceBypassAsync, type InvokeParams, type InvokeResult, type Message } from '../_core/llm';
import { preShapePrompt, enforce, enforceDegraded, recordGeometryEnforcement } from './geometry-controller';
import { composeDeepGeometryVerdict, type DeepGeometryVerdict } from './geometry-deep-verdict';
import { decideGeometryInfluence } from './geometry-verdict-influence';
import { decideManifoldInfluence } from './manifold-verdict-influence';
import { getManifoldSessionTrajectory } from '../emotional-geometry-runtime/geometry/manifold-session-state';
import { decideRecallInfluence } from './recall-verdict-influence';
import { isFeatureEnabled } from '../emotional-geometry-runtime/feature-flags';
import { attachCanonicalReceiptIfEnabled, type CanonicalVerdictReceipt } from './canonical-verdict-receipt';
import { selectShadowContent, classifyEnforcementOutcome } from './geometry-content-select';
import { recordGeometryShadow } from './geometry-shadow-record';
import { recordGeometryEvalCapture } from './geometry-eval-capture-record';
import { recognizeRepeatFailure, lookupRepeatFailure, type RepeatFailureRecognitionInput } from './repeat-failure-recognition';
import { recordDegradedCause } from './degraded-cause-record';
import { requestApproval, REGULATED_SURFACES, FAIL_CLOSED_ERROR } from './regulated-surface-preapproval';
import { createHash } from 'crypto';
import { unsafeCast } from '../../shared/type-bridge';
import { preGenerationHook, postGenerationHook, type GeometryPreGenerationResult, type GeometryPostGenerationResult } from '../emotional-geometry-runtime/geometry-runtime-bridge';
import { advancedPreGenerationHook, advancedPostGenerationHook } from '../neurocosmology-runtime-advanced/integration-hooks';
import { createInitialState, updateBaseDimensions, type CanonicalEmotionalState } from '../emotional-geometry-runtime/state/EmotionalState';
import { persistGeometryData } from '../emotional-geometry-runtime/session-persistence';
import { evaluateAlerts } from '../emotional-geometry-runtime/geometry-alerting';

const log = createLogger('governance');

// ============================================================================
// TYPES
// ============================================================================

export interface GovernedGenerateParams {
  /** LLM messages (system + user + assistant history) */
  messages: InvokeParams['messages'];
  /** Model override (optional — uses default if not specified) */
  model?: string;
  /** Content type for governance classification */
  contentType?: string;
  /** Content role: user-facing, internal, admin, system */
  contentRole?: 'user-facing' | 'internal' | 'admin' | 'system';
  /** Product ID for auto-registration and per-product governance */
  productId?: string;
  /** Product name (used for auto-registration) */
  productName?: string;
  /** Surface ID for governance context routing */
  surfaceId?: string;
  /** Audience type for tone calibration */
  audienceType?: 'general' | 'professional' | 'technical' | 'legal' | 'medical';
  /** System prompt override (prepended to messages) */
  systemPrompt?: string;
  /** Skip stabilization (useful for creative content) */
  skipStabilization?: boolean;
  /** Max retries on regenerate verdict (default: 1) */
  maxRetries?: number;
  /** LLM parameters passthrough */
  temperature?: number;
  max_tokens?: number;
  response_format?: InvokeParams['response_format'];
  tools?: InvokeParams['tools'];
  tool_choice?: InvokeParams['tool_choice'];
  /**
   * FAIL-CLOSED geometry-eval capture eligibility. Default (undefined) → NOT
   * eligible → no capture row is written even when GEOMETRY_EVAL_CAPTURE_ENABLED
   * is on. Only an explicitly-marked internal caller opts in; externally-reachable
   * / unscoped callers (e.g. the customer-facing MCP bridge) are skipped by
   * construction. Not flipped for any caller in this packet.
   */
  captureEligible?: boolean;
  /**
   * FAIL-CLOSED excerpt eligibility. Default (undefined) → the ≤160-char free-text
   * excerpt is withheld (structured capture fields are still retained). Stays off
   * until a caller is classified safe-for-excerpt, because the regex suppressor is
   * not a privacy boundary for non-shape PII/PHI.
   */
  excerptEligible?: boolean;
  /**
   * Authenticated tenant, populated ONLY by a caller that resolved it from a
   * validated inference credential (resolveInferenceTenant → org-<id>/user-<id>).
   * No current caller sets this (see packet trace); untrusted callers MUST leave
   * it undefined. It is the ONLY input that can raise the canonical receipt to
   * `authenticated_tenant` (a trusted `source`, e.g. 'inference_auth').
   */
  authenticatedTenant?: { tenantId: string; source: string };
}

export interface GovernedGenerateResult {
  /** Final content after governance */
  content: string;
  /** Whether governance was applied */
  governed: boolean;
  /** Governance decision: pass, stabilize, block, regenerate */
  decision: string;
  /** Whether content was modified by governance */
  modified: boolean;
  /** Gravito run ID for audit trail */
  gravito_run_id?: string;
  /** Governance score (0-100) */
  score: number;
  /** Issues found during governance */
  issues: Array<{ type: string; severity: string; description: string }>;
  /** Audit trail for debugging */
  auditTrail: string[];
  /** Processing time in ms */
  processingTimeMs: number;
  /** Whether failsafe/degraded mode was used */
  degradedMode: boolean;
  /** Raw LLM result (for advanced consumers) */
  rawResult?: InvokeResult;
  /** Product registration status */
  productRegistered: boolean;
  /**
   * Canonical verdict receipt (Gate→Remember→Compound→Earn-Authority). Present
   * only when CANONICAL_VERDICT_RECEIPT_ENABLED; default-OFF ⇒ absent
   * (byte-identical).
   */
  canonical_receipt?: CanonicalVerdictReceipt;
}

// ============================================================================
// METRICS
// ============================================================================

interface GovernedGenerateMetrics {
  totalCalls: number;
  totalPassed: number;
  totalStabilized: number;
  totalBlocked: number;
  totalRegenerated: number;
  totalDegraded: number;
  totalErrors: number;
  avgLatencyMs: number;
  byProduct: Record<string, { calls: number; blocked: number; degraded: number }>;
}

const _metrics: GovernedGenerateMetrics = {
  totalCalls: 0,
  totalPassed: 0,
  totalStabilized: 0,
  totalBlocked: 0,
  totalRegenerated: 0,
  totalDegraded: 0,
  totalErrors: 0,
  avgLatencyMs: 0,
  byProduct: {},
};

export function getGovernedGenerateMetrics(): GovernedGenerateMetrics {
  return { ..._metrics };
}

// ============================================================================
// GEOMETRY→VERDICT INFLUENCE COUNTER (packet gravito_behavior_wiring_proof_a)
// Monotonic in-memory counter of geometry-driven verdict ESCALATIONS to block.
// Only ever increments when GEOMETRY_VERDICT_INFLUENCE_ENABLED is ON and a
// content-driven deep geometry block escalates the live verdict. Mirrors the
// review-health counter style (private state + read-only getter + test reset).
// ============================================================================

let _geometryInfluenceEscalationCount = 0;

/** Read-only count of geometry→verdict escalations since boot. */
export function getGeometryInfluenceEscalationCount(): number {
  return _geometryInfluenceEscalationCount;
}

/** Reset the geometry→verdict escalation counter (for testing). */
export function resetGeometryInfluenceEscalationCount(): void {
  _geometryInfluenceEscalationCount = 0;
}

/**
 * WIRED SEAM (default-OFF, escalate-only) — reconcile the live co-processor
 * verdict with the DEEP geometry shadow verdict.
 *
 * Behind GEOMETRY_VERDICT_INFLUENCE_ENABLED: when a CONTENT-driven deep geometry
 * `block` is present and the live verdict is not already `block`, escalate the
 * response to `block` using the SAME safe-fallback producer applyVerdict uses
 * (co-processor/index.ts:416) — so the block message never diverges from the
 * canonical block path. Escalate-only: it can only make the gate STRICTER.
 *
 * FLAG-OFF ⇒ byte-identical to today: zero new work runs and the baseline
 * {content, decision, modified} is returned unchanged. NEVER throws into the
 * response path — on any error it returns the unmodified baseline plus an audit
 * note. The counter is incremented ONLY on a real escalation.
 */
export function applyGeometryInfluence(
  llmResult: InvokeResult,
  verdict: CoProcessorVerdict,
  deepGeoResult: DeepGeometryVerdict,
  currentContent: string,
  auditTrail: string[],
): { content: string; decision: CoProcessorDecision; modified: boolean } {
  const baseline = {
    content: currentContent,
    decision: verdict.decision,
    modified: verdict.wasModified,
  };

  // FLAG GATE: OFF ⇒ zero new work, byte-identical baseline.
  if (!isFeatureEnabled('GEOMETRY_VERDICT_INFLUENCE_ENABLED')) {
    return baseline;
  }

  try {
    const influence = decideGeometryInfluence(verdict.decision, deepGeoResult);
    if (!influence.escalate) {
      return baseline;
    }

    // Reuse the canonical safe-fallback producer (applyVerdict block branch) so
    // the withheld content is identical to a native co-processor block.
    const blockedResult = applyVerdict(llmResult, { ...verdict, decision: 'block' });
    _geometryInfluenceEscalationCount++;
    auditTrail.push(
      `[GEOMETRY-INFLUENCE] Escalated ${verdict.decision} → block on: ${influence.triggeringSignals.join(', ')}`,
    );
    return {
      content: extractContent(blockedResult),
      decision: 'block',
      modified: true,
    };
  } catch (influenceErr) {
    // Defensive: the influence path must NEVER throw into the response path.
    auditTrail.push(
      `[GEOMETRY-INFLUENCE] Skipped (non-blocking error): ${influenceErr instanceof Error ? influenceErr.message : String(influenceErr)}`,
    );
    return baseline;
  }
}

// ============================================================================
// RECALL→VERDICT INFLUENCE COUNTER (packet gravito_recall_wiring_proof_a)
// Monotonic in-memory counter of recall-driven verdict ESCALATIONS to block.
// Only ever increments when GEOMETRY_RECALL_INFLUENCE_ENABLED is ON and a
// recognized prior persisted FAILING verdict escalates the live verdict. Mirrors
// the geometry-influence counter (private state + read-only getter + test reset).
// ============================================================================

let _recallInfluenceEscalationCount = 0;

/** Read-only count of recall→verdict escalations since boot. */
export function getRecallInfluenceEscalationCount(): number {
  return _recallInfluenceEscalationCount;
}

/** Reset the recall→verdict escalation counter (for testing). */
export function resetRecallInfluenceEscalationCount(): void {
  _recallInfluenceEscalationCount = 0;
}

/**
 * WIRED SEAM (default-OFF, escalate-only) — reconcile the live (already
 * geometry-influenced) verdict with a RECOGNIZED prior-failing RECALL outcome.
 * The RECALL half of the remember → recall → prevent loop.
 *
 * Behind GEOMETRY_RECALL_INFLUENCE_ENABLED: perform the IN-PATH recall READ
 * (lookupRepeatFailure — product-scoped, salt-gated, bounded, fail-open) and,
 * when a recognized prior persisted FAILING verdict (same product + salted
 * content_hash, prior decision ∈ {block, regenerate}) is found and the current
 * verdict is not already `block`, ESCALATE the response to `block` using the SAME
 * safe-fallback producer applyVerdict uses (co-processor/index.ts:416) — so the
 * block message never diverges from the canonical block path. Escalate-only: it
 * can only make the gate STRICTER. Product-scoped / fail-closed: a null
 * product_id or a null outcome never escalates.
 *
 * FLAG-OFF ⇒ byte-identical to today: zero new work runs (NO DB read) and the
 * chained-in `current` {content, decision, modified} is returned unchanged.
 * NEVER throws into the response path — on any error it returns the unmodified
 * `current` plus an audit note. The counter is incremented ONLY on a real
 * escalation.
 */
export async function applyRecallInfluence(
  llmResult: InvokeResult,
  verdict: CoProcessorVerdict,
  current: { content: string; decision: CoProcessorDecision; modified: boolean },
  recallInput: RepeatFailureRecognitionInput,
  auditTrail: string[],
): Promise<{ content: string; decision: CoProcessorDecision; modified: boolean }> {
  // FLAG GATE: OFF ⇒ zero new work (no in-path DB read), byte-identical `current`.
  if (!isFeatureEnabled('GEOMETRY_RECALL_INFLUENCE_ENABLED')) {
    return current;
  }

  try {
    // In-path bounded, fail-open, product-scoped recall READ (never throws).
    const recallOutcome = await lookupRepeatFailure(recallInput);
    const influence = decideRecallInfluence(current.decision, recallOutcome);
    if (!influence.escalate) {
      return current;
    }

    // Reuse the canonical safe-fallback producer (applyVerdict block branch) so
    // the withheld content is identical to a native co-processor block.
    const blockedResult = applyVerdict(llmResult, { ...verdict, decision: 'block' });
    _recallInfluenceEscalationCount++;
    auditTrail.push(
      `[RECALL-INFLUENCE] Escalated ${current.decision} → block: prior failing verdict ` +
        `(${influence.firstSeenDecision} ×${influence.priorFailureCount}, run ${influence.firstSeenRunId})`,
    );
    return {
      content: extractContent(blockedResult),
      decision: 'block',
      modified: true,
    };
  } catch (influenceErr) {
    // Defensive: the recall-influence path must NEVER throw into the response path.
    auditTrail.push(
      `[RECALL-INFLUENCE] Skipped (non-blocking error): ${influenceErr instanceof Error ? influenceErr.message : String(influenceErr)}`,
    );
    return current;
  }
}

// ============================================================================
// MANIFOLD→VERDICT INFLUENCE COUNTER (packet manifold_verdict_influence_proof_a)
// Monotonic in-memory counter of manifold-driven verdict ESCALATIONS to block.
// Only ever increments when MANIFOLD_VERDICT_INFLUENCE_ENABLED is ON and an
// UNSTABLE accumulated-trajectory attractor class escalates the live verdict.
// Mirrors the geometry/recall-influence counters (private state + getter + reset).
// ============================================================================

let _manifoldInfluenceEscalationCount = 0;

/** Read-only count of manifold→verdict escalations since boot. */
export function getManifoldInfluenceEscalationCount(): number {
  return _manifoldInfluenceEscalationCount;
}

/** Reset the manifold→verdict escalation counter (for testing). */
export function resetManifoldInfluenceEscalationCount(): void {
  _manifoldInfluenceEscalationCount = 0;
}

/**
 * WIRED SEAM (default-OFF, escalate-only) — reconcile the live (already
 * content/recall-influenced) verdict with the MANIFOLD attractor class of the
 * accumulated per-session state trajectory. The final link of the
 * score → remember → recall → PREVENT spine wired for the deep-math signal.
 *
 * Behind MANIFOLD_VERDICT_INFLUENCE_ENABLED: read the in-memory accumulated
 * trajectory for this session (getManifoldSessionTrajectory — the default-OFF
 * accumulator from manifold_session_state_prereq_a), classify it with the
 * corrected Jacobian estimator, and when it is a NON-DEGENERATE, UNSTABLE
 * attractor (saddle-point / unstable-node / unstable-spiral) and the current
 * verdict is not already `block`, ESCALATE to `block` via the SAME safe-fallback
 * producer applyVerdict uses (co-processor/index.ts:416). Escalate-only: it can
 * only make the gate STRICTER. Degenerate/empty/too-short trajectories never
 * escalate (a constant trajectory is spuriously `saddle-point` and is gated out
 * in decideManifoldInfluence BEFORE classification).
 *
 * FLAG-OFF ⇒ byte-identical to today: zero new work runs (NO trajectory read) and
 * the chained-in `current` {content, decision, modified} is returned unchanged.
 * NEVER throws into the response path — on any error it returns the unmodified
 * `current` plus an audit note. The counter increments ONLY on a real escalation.
 */
export function applyManifoldInfluence(
  llmResult: InvokeResult,
  verdict: CoProcessorVerdict,
  current: { content: string; decision: CoProcessorDecision; modified: boolean },
  ctx: { sessionId: string | null },
  auditTrail: string[],
): { content: string; decision: CoProcessorDecision; modified: boolean } {
  // FLAG GATE: OFF ⇒ zero new work (no trajectory read), byte-identical `current`.
  if (!isFeatureEnabled('MANIFOLD_VERDICT_INFLUENCE_ENABLED')) {
    return current;
  }

  try {
    // Fail-closed: no session ⇒ no trajectory ⇒ no escalation.
    if (!ctx.sessionId) {
      return current;
    }
    const trajectory = getManifoldSessionTrajectory(ctx.sessionId);
    const influence = decideManifoldInfluence(current.decision, trajectory);
    if (!influence.escalate) {
      return current;
    }

    // Reuse the canonical safe-fallback producer (applyVerdict block branch) so
    // the withheld content is identical to a native co-processor block.
    const blockedResult = applyVerdict(llmResult, { ...verdict, decision: 'block' });
    _manifoldInfluenceEscalationCount++;
    auditTrail.push(
      `[MANIFOLD-INFLUENCE] Escalated ${current.decision} → block on unstable manifold: ` +
        `${influence.manifoldClass} (trajectory=${influence.trajectoryLength}, flag=MANIFOLD_VERDICT_INFLUENCE_ENABLED)`,
    );
    return {
      content: extractContent(blockedResult),
      decision: 'block',
      modified: true,
    };
  } catch (influenceErr) {
    // Defensive: the manifold-influence path must NEVER throw into the response path.
    auditTrail.push(
      `[MANIFOLD-INFLUENCE] Skipped (non-blocking error): ${influenceErr instanceof Error ? influenceErr.message : String(influenceErr)}`,
    );
    return current;
  }
}

// ============================================================================
// CORE: governedGenerate
// ============================================================================

export async function governedGenerate(
  params: GovernedGenerateParams
): Promise<GovernedGenerateResult> {
  // RE-ENTRANCY GUARD (internal governance evaluations): the co-processor's
  // prevention layer calls governedGenerate for its AI-based evaluation, so an
  // unguarded pipeline recurses infinitely (governedGenerate → co-processor
  // post-generation → prevention layer → governedGenerate → …). Step 6 below
  // runs the co-processor inside the LLM governance-bypass context (the same
  // AsyncLocalStorage mechanism invokeLLM uses for recursion prevention), so a
  // governedGenerate call arriving INSIDE that context is by definition part of
  // an internal governance evaluation — serve it with a single ungoverned
  // safeLLM call instead of re-governing governance's own plumbing.
  if (getGovernanceBypassState().bypassed) {
    return generateInternalBypass(params);
  }

  const startTime = Date.now();
  const auditTrail: string[] = [];
  const maxRetries = params.maxRetries ?? 1;
  let degradedMode = false;
  let productRegistered = false;

  _metrics.totalCalls++;

  // Step 1: Auto-register product (non-blocking on failure)
  if (params.productId) {
    try {
      await registerSurfaceIfMissing({
        productId: params.productId,
        productName: params.productName,
        registrationSource: 'governance_request',
      });
      productRegistered = true;
      auditTrail.push(`[REGISTER] Product ${params.productId} registered/cached`);
    } catch (err) {
      auditTrail.push(`[REGISTER] Failed (non-blocking): ${err}`);
    }
  }

  // Track per-product metrics
  const productKey = params.productId || 'internal';
  if (!_metrics.byProduct[productKey]) {
    _metrics.byProduct[productKey] = { calls: 0, blocked: 0, degraded: 0 };
  }
  _metrics.byProduct[productKey].calls++;

  // Step 2: Resolve product-aware governance context
  const govContext = resolveGovernanceContext({
    productId: params.productId,
    surfaceId: params.surfaceId,
    contentRole: params.contentRole,
    contentType: params.contentType,
    audienceType: params.audienceType,
  });
  recordContextResolution(govContext);
  auditTrail.push(`[CONTEXT] Profile: ${govContext.profile.id}, strictness: ${govContext.profile.strictness}, overrides: [${govContext.overridesApplied.join(', ')}]`);

  // Step 2.5: Control Plane Enforcement Gate
  // AUTHORITATIVE: Control plane is THE gate — not a suggestion layer
  const { enforce: cpEnforce, getEnforcementMode } = await import('../control-plane');
  // IDENTITY STAMP (identity only — never content, never prompts): the audit
  // rows this gate writes must name their caller so ledger readers can
  // attribute entries without log archaeology. surfaceType/callerId are read
  // through a widened view — GovernedGenerateParams does not declare them, but
  // runtime callers may pass them.
  const identityView = params as GovernedGenerateParams & { surfaceType?: string; callerId?: string };
  const cpResult = await cpEnforce({
    agentId: params.productId || 'default',
    action: 'generate',
    content: params.messages.map(m => typeof m.content === 'string' ? m.content : '').join(' ').slice(0, 500),
    metadata: {
      surface: params.surfaceId || 'unknown',
      riskScore: 0.5,
      contentType: params.contentType,
      contentRole: params.contentRole,
      productId: params.productId || 'default',
      surfaceType: identityView.surfaceType ?? params.contentType ?? null,
      callerId: identityView.callerId ?? null,
    },
  });
  const cpMode = getEnforcementMode();
  auditTrail.push(`[CONTROL-PLANE:${cpMode}] ${cpResult.allowed ? 'ALLOWED' : 'BLOCKED'} — reason: ${cpResult.reason}`);
  auditTrail.push(`[CONTROL-PLANE] checks: ${Object.entries(cpResult.checks).map(([name, c]) => `${name}:${c.passed}`).join(', ')}`);
  if (!cpResult.allowed) {
    // In observe/alert modes, log but don't block; in soft/hard modes, actually block
    if (cpMode === 'hard' || cpMode === 'soft') {
      return {
        content: cpMode === 'soft' ? `[Governance Notice] This request was flagged: ${cpResult.reason}` : '',
        governed: true,
        decision: 'block',
        modified: false,
        score: 0,
        issues: [{
          type: 'control_plane_block',
          severity: 'critical',
          description: `Control plane ${cpMode}-blocked: ${cpResult.reason}`,
        }],
        auditTrail,
        processingTimeMs: Date.now() - startTime,
        degradedMode: false,
        productRegistered,
      };
    }
    // observe/alert: log the block decision but proceed
    auditTrail.push(`[CONTROL-PLANE:${cpMode}] Would have blocked but mode is ${cpMode} — proceeding`);
  }

  // Step 3: Build messages with governance context injection
  const contextInjection = buildGovernanceInjection(govContext);
  const messages = buildMessages(params, contextInjection);

  // Step 3: Generate + Govern (with retry on regenerate)
  let attempt = 0;
  let lastResult: GovernedGenerateResult | null = null;

  while (attempt <= maxRetries) {
    attempt++;
    auditTrail.push(`[ATTEMPT] ${attempt}/${maxRetries + 1}`);

    try {
      const result = await generateAndGovern(messages, params, auditTrail);
      lastResult = result;

      if (result.decision === 'regenerate' && attempt <= maxRetries) {
        auditTrail.push(`[REGENERATE] Retrying (attempt ${attempt + 1})...`);
        continue;
      }

      // Final result
      result.auditTrail = auditTrail;
      result.processingTimeMs = Date.now() - startTime;
      result.degradedMode = degradedMode;
      result.productRegistered = productRegistered;

      updateMetrics(result, productKey, startTime);

      // Increment product activity counter
      if (params.productId) {
        incrementActivityCounter(params.productId, 'governance_request', 'governed_llm').catch(() => {});
      }

      return result;
    } catch (err) {
      auditTrail.push(`[ERROR] Attempt ${attempt} failed: ${err instanceof Error ? err.message : String(err)}`);

      // If governance pipeline fails, use degraded mode
      if (attempt > maxRetries) {
        log.warn(`[GovernedGenerate] All attempts failed, entering degraded mode: ${err instanceof Error ? err.message : String(err)}`);
        degradedMode = true;
        _metrics.totalDegraded++;
        _metrics.byProduct[productKey].degraded++;

        // DEGRADED-CAUSE LEDGER STAMP — the fall to degraded mode was
        // previously log-only; record WHY in the control-plane ledger
        // (action 'generate:degraded'). Fire-and-forget and never-throwing: a
        // failed write can NEVER affect the degraded response below. The cause
        // is a technical error string head-truncated to 200 chars — identity
        // only, never content, never prompts.
        recordDegradedCause({
          cause: err,
          productId: params.productId,
          surfaceType: identityView.surfaceType ?? params.contentType ?? null,
        });

        try {
          const degradedResult = await generateDegradedMode(messages, params, auditTrail);
          degradedResult.processingTimeMs = Date.now() - startTime;
          degradedResult.degradedMode = true;
          degradedResult.productRegistered = productRegistered;
          updateMetrics(degradedResult, productKey, startTime);
          return degradedResult;
        } catch (degradedErr) {
          _metrics.totalErrors++;
          return {
            content: '',
            governed: false,
            decision: 'error',
            modified: false,
            score: 0,
            issues: [{ type: 'system_error', severity: 'critical', description: `Governance pipeline failed: ${degradedErr}` }],
            auditTrail,
            processingTimeMs: Date.now() - startTime,
            degradedMode: true,
            productRegistered,
          };
        }
      }
    }
  }

  // Should not reach here, but safety net
  return lastResult || {
    content: '',
    governed: false,
    decision: 'error',
    modified: false,
    score: 0,
    issues: [],
    auditTrail,
    processingTimeMs: Date.now() - startTime,
    degradedMode: true,
    productRegistered,
  };
}

// ============================================================================
// INTERNAL: Generate + Govern Pipeline
// ============================================================================

/** Content types that map 1:1 onto a co-processor ContentDomain override. */
const CONTENT_DOMAINS: ReadonlySet<string> = new Set([
  'medical', 'financial', 'legal', 'marketing', 'product', 'governance', 'general',
]);

async function generateAndGovern(
  messages: InvokeParams['messages'],
  params: GovernedGenerateParams,
  auditTrail: string[],
): Promise<GovernedGenerateResult> {
  // Pre-generation: classify content and build signals
  const contentType = params.contentType || 'general';
  const preSignals = coProcessorPreGenerate(
    { messages },
    CONTENT_DOMAINS.has(contentType) ? { domain: contentType as ContentDomain } : undefined,
  );
  auditTrail.push(`[PRE-GEN] Domain: ${preSignals.signals.classification.domain}, Risk: ${preSignals.signals.classification.riskTier}`);

  // ========================================================================
  // PRE-GENERATION GATING — Regulated surfaces must be approved BEFORE generation
  // ========================================================================
  // If the content domain is regulated (e.g., medical, legal, financial) and
  // the product has opted into pre-approval, we must gate here.
  if (REGULATED_SURFACES.has(preSignals.signals.classification.domain)) {
    const contentHash = createHash('sha256')
      .update(messages.map(m => (typeof m.content === 'string' ? m.content : JSON.stringify(m.content))).join('\n'))
      .digest('hex');
    const approval = await requestApproval({
      surfaceType: preSignals.signals.classification.domain,
      contentHash,
      requesterId: params.productId,
    });

    if (!approval.approved) {
      auditTrail.push(`[REGULATED] Pre-approval denied for domain: ${preSignals.signals.classification.domain}. Reason: ${approval.denialReason}`);
      throw new Error(FAIL_CLOSED_ERROR);
    }
    auditTrail.push(`[REGULATED] Pre-approval granted for domain: ${preSignals.signals.classification.domain}`);
  }

  // Step 3.5: Emotional Geometry Runtime — Pre-Generation Hook
  let geometryPreResult: GeometryPreGenerationResult | null = null;
  try {
    geometryPreResult = await preGenerationHook({
      sessionId: params.surfaceId || 'default',
      userId: params.productId || 'internal',
      prompt: typeof messages[messages.length - 1]?.content === 'string' ? messages[messages.length - 1].content as string : '',
      conversationHistory: messages.filter(m => m.role === 'user').map(m => typeof m.content === 'string' ? m.content : '').slice(-10),
    });
    auditTrail.push(`[GEOMETRY-PRE] Fixation: ${geometryPreResult.fixationRisk.toFixed(3)}, Stability: ${geometryPreResult.stabilityClass}, Drift: ${geometryPreResult.driftScore.toFixed(3)}, Eigen: ${geometryPreResult.eigenClassification}, Constrain: ${geometryPreResult.shouldConstrain}, Time: ${geometryPreResult.computeTimeMs.toFixed(2)}ms`);

    if (geometryPreResult.shouldConstrain) {
      auditTrail.push(`[GEOMETRY-PRE] Constraints injected: [${geometryPreResult.constraintsInjected.join(', ')}]`);
    }
  } catch (geoErr) {
    auditTrail.push(`[GEOMETRY-PRE] Failed (non-blocking): ${geoErr instanceof Error ? geoErr.message : String(geoErr)}`);
  }

  // Step 3.6: Advanced Neurocosmology — Pre-Generation Hook (shadow mode)
  try {
    const advancedPre = await advancedPreGenerationHook({
      currentState: buildCanonicalState(
        geometryPreResult?.stateSnapshot,
        params.surfaceId || 'default',
        params.productId || 'internal',
      ),
      stateHistory: [],
    });
    if (advancedPre.enabled) {
      auditTrail.push(`[NEURO-PRE] Mode: ${advancedPre.mode}, Singularity: ${advancedPre.singularity?.isSingularity ?? false}, PhaseShift: ${advancedPre.phaseTransition?.isPhaseShift ?? false}, Invariants violated: ${advancedPre.invariantReport?.violations?.length ?? 0}, Time: ${advancedPre.computeTimeMs.toFixed(2)}ms`);
    }
  } catch (advErr) {
    auditTrail.push(`[NEURO-PRE] Failed (non-blocking): ${advErr instanceof Error ? advErr.message : String(advErr)}`);
  }

  // Step 4: Pre-shape prompt for geometry enforcement
  const { shapedMessages } = preShapePrompt(messages, unsafeCast(params, "boundary cast"));
  auditTrail.push(`[GEOMETRY] Prompt shaped for geometry enforcement.`);

  // Step 5: LLM generation
  const llmResult = await safeLLM(
    {
      messages: unsafeCast<InvokeParams['messages']>(shapedMessages, "preShapePrompt widens role to string; runtime shape is Message[]"),
      model: params.model,
      max_tokens: params.max_tokens,
      response_format: params.response_format,
      tools: params.tools,
      tool_choice: params.tool_choice,
    },
    { context: 'governed-generate' },
  );
  if (isFallbackResponse(llmResult)) {
    // safeLLM never throws — it returns a structured degradation response.
    // The MAIN pipeline must NOT continue with that fallback content (geometry
    // and the verdict would score degradation JSON), so throw here and let the
    // existing retry/degraded machinery engage exactly as designed.
    let reason = 'all LLM routes failed';
    try {
      const parsed = JSON.parse(extractContent(llmResult)) as { _error?: string };
      if (parsed?._error) reason = parsed._error;
    } catch { /* fallback content is not always JSON — keep the generic reason */ }
    throw new Error(`LLM unavailable: ${reason}`);
  }
  auditTrail.push(`[LLM] Raw generation complete. Tokens: ${llmResult.usage?.completion_tokens ?? 0} completion / ${llmResult.usage?.total_tokens ?? 0} total.`);

  // Step 5.5: Emotional Geometry Runtime — Post-Generation Hook
  let geometryPostResult: GeometryPostGenerationResult | null = null;
  try {
    if (geometryPreResult) {
      geometryPostResult = await postGenerationHook({
        sessionId: params.surfaceId || 'default',
        output: extractContent(llmResult),
        preResult: geometryPreResult,
      });
      auditTrail.push(`[GEOMETRY-POST] EntropyΔ: ${geometryPostResult.entropyDelta.toFixed(4)}, CurvatureΔ: ${geometryPostResult.curvatureDelta.toFixed(4)}, Loop: ${geometryPostResult.loopDetected}, Time: ${geometryPostResult.computeTimeMs.toFixed(2)}ms`);
    }
  } catch (geoPostErr) {
    auditTrail.push(`[GEOMETRY-POST] Failed (non-blocking): ${geoPostErr instanceof Error ? geoPostErr.message : String(geoPostErr)}`);
  }

  // Step 5.6: Advanced Neurocosmology — Post-Generation Hook (shadow mode)
  let neuroData: { singularityDetected: boolean; phaseTransitionDetected: boolean; invariantViolations: number } | undefined;
  try {
    const advancedPost = await advancedPostGenerationHook({
      updatedState: buildCanonicalState(
        geometryPreResult?.stateSnapshot,
        params.surfaceId || 'default',
        params.productId || 'internal',
      ),
      stateHistory: [],
    });
    if (advancedPost.enabled) {
      auditTrail.push(`[NEURO-POST] Singularity: ${advancedPost.singularity?.isSingularity ?? false}, PhaseShift: ${advancedPost.phaseTransition?.isPhaseShift ?? false}, Invariants: ${advancedPost.invariantReport?.violations?.length ?? 0}, Time: ${advancedPost.computeTimeMs.toFixed(2)}ms`);
    }
    // Capture neuro data for persistence
    if (advancedPost.enabled) {
      neuroData = {
        singularityDetected: advancedPost.singularity?.isSingularity ?? false,
        phaseTransitionDetected: advancedPost.phaseTransition?.isPhaseShift ?? false,
        invariantViolations: advancedPost.invariantReport?.violations?.length ?? 0,
      };
    }
  } catch (advPostErr) {
    auditTrail.push(`[NEURO-POST] Failed (non-blocking): ${advPostErr instanceof Error ? advPostErr.message : String(advPostErr)}`);
  }

  // Step 5.7: Persist geometry data to database (non-blocking, fire-and-forget)
  if (geometryPreResult) {
    try {
      const { getGeometryMetrics } = await import('../emotional-geometry-runtime/geometry-metrics');
      const currentMetrics = getGeometryMetrics();
      const generationIndex = currentMetrics.counters.preHookTotal?.value ?? 0;
      const persistResult = await persistGeometryData({
        sessionId: params.surfaceId || 'default',
        productId: params.productId,
        surfaceId: params.surfaceId,
        generationIndex,
        preResult: geometryPreResult,
        postResult: geometryPostResult,
        neuroAdvanced: neuroData,
      });
      if (persistResult.success) {
        auditTrail.push(`[GEOMETRY-PERSIST] Session: ${persistResult.sessionPersisted}, Snapshot: ${persistResult.snapshotPersisted}, Events: ${persistResult.eventCount}`);
      } else {
        auditTrail.push(`[GEOMETRY-PERSIST] Partial failure: ${persistResult.error}`);
      }
    } catch (persistErr) {
      auditTrail.push(`[GEOMETRY-PERSIST] Failed (non-blocking): ${persistErr instanceof Error ? persistErr.message : String(persistErr)}`);
    }

    // Step 5.8: Evaluate geometry alerting rules (non-blocking, fire-and-forget)
    try {
      const alertsFired = await evaluateAlerts({
        sessionId: params.surfaceId || 'default',
        preResult: geometryPreResult,
        postResult: geometryPostResult,
        neuroAdvanced: neuroData,
      });
      if (alertsFired > 0) {
        auditTrail.push(`[GEOMETRY-ALERTS] ${alertsFired} alert(s) fired`);
      }
    } catch (alertErr) {
      auditTrail.push(`[GEOMETRY-ALERTS] Failed (non-blocking): ${alertErr instanceof Error ? alertErr.message : String(alertErr)}`);
    }
  }

  // Step 6: Post-generation analysis (pre-filter → Gravito inline → stabilize →
  // decide). Runs inside the governance-bypass context — mirroring invokeLLM's
  // own coProcessorPostGenerate call — so the internal LLM work it triggers
  // (prevention-layer AI evaluation, Gravito inline review) cannot recurse back
  // into a fully-governed pipeline (see the re-entrancy guard in
  // governedGenerate).
  const verdict = await withGovernanceBypassAsync(() =>
    coProcessorPostGenerate(llmResult, preSignals.signals, {
      skipStabilization: params.skipStabilization,
      callerId: params.productId,
    })
  );
  auditTrail.push(`[POST-GEN] Heuristics: ${verdict.postAnalysis.issues.map(i => i.type).join(', ') || 'none'}`);

  // Step 7: Apply verdict (enforcement) — block → safe fallback message,
  // stabilize → fixed content, pass/regenerate → unchanged result.
  const enforcedResult = applyVerdict(llmResult, verdict);
  auditTrail.push(`[VERDICT] Decision: ${verdict.decision}, Score: ${verdict.postAnalysis.score}, Gravito ID: ${verdict.gravito_run_id}`);

  // Step 8: Score geometry on the generated content (SHADOW MODE — observe only).
  // `geoResult` is the GeometryEnforcementResult OBJECT returned by enforce()
  // ({ passed, decision, score, promptConstraints, rewriteDirectives, auditTrail }).
  // In shadow mode geometry does NOT transform/gate content, so the response
  // `content` is the ORIGINAL generated text — NOT the enforce() object (the prior
  // `finalContent = geoResult` leaked that object as `content: string`) and NOT a
  // geometry-rewritten string (applying geoResult.decision to rewrite/block is a
  // later phase). selectShadowContent encodes that invariant.
  const generatedContent = extractContent(enforcedResult);
  const geoResult = enforce(generatedContent, unsafeCast(params, "boundary cast"));
  const finalContent = selectShadowContent(generatedContent, geoResult);

  // Step 8 (DEEP): compose the DEEP shadow verdict from the ALREADY-COMPUTED
  // Step 3.5/5.5 state-vector hook results (geometryPreResult /
  // geometryPostResult), the shallow enforce() verdict, and the generated
  // content (deep-content layer v1 lives inside geometry-deep-verdict.ts).
  // ESCALATION-ONLY and NON-GATING: the composed verdict feeds the audit
  // trail, the enforcement metrics/memory, and the shadow ledger below — the
  // response `content` stays selectShadowContent(generatedContent, geoResult)
  // exactly as before. Geometry still gates NOTHING.
  const deepGeoResult = composeDeepGeometryVerdict(
    geoResult,
    geometryPreResult,
    geometryPostResult,
    generatedContent,
  );
  auditTrail.push(
    `[GEOMETRY-DEEP] Shadow verdict: ${deepGeoResult.decision} (shallow: ${geoResult.decision}, ` +
      `signals: ${deepGeoResult.deep.signals.map(s => s.trigger).join(', ') || 'none'}) — non-gating.`,
  );
  // Enforced-vs-passed is derived from the COMPOSED geometry verdict
  // (deepGeoResult.decision) — the shallow-only record predates the deep layer.
  if (classifyEnforcementOutcome(deepGeoResult) === 'enforced') {
    auditTrail.push(`[GEOMETRY] Enforcement recorded (decision: ${deepGeoResult.decision}).`);
  }
  recordGeometryEnforcement(deepGeoResult, {
    productId: params.productId,
    surfaceId: params.surfaceId,
    contentType: params.contentType,
  });

  // SHADOW MODE — record the geometry-vs-live-verdict agreement to the canary
  // ledger. Fire-and-forget, flag-gated (GEOMETRY_RUNTIME_ENABLED), write-only,
  // and never throws into this response path. Changes NOTHING observable.
  // `verdict` is a CoProcessorVerdict at runtime (its `.decision` / `.gravito_run_id`
  // are already read below in the return); it is viewed here through the file's
  // existing boundary-cast helper so this shadow addition introduces no new type
  // errors and reads the exact same runtime values.
  // The ledger receives the COMPOSED deep verdict (same input contract:
  // decision/score fields) so the canary — and the operator-truth
  // geometryCanary panel reading it — surfaces the deep shadow signal.
  const verdictView = unsafeCast<{ decision: string; gravito_run_id?: string }>(verdict, "boundary cast");
  recordGeometryShadow({
    geometryDecision: deepGeoResult.decision,
    liveVerdictDecision: verdictView.decision,
    gravitoRunId: verdictView.gravito_run_id ?? null,
    geometryScore: deepGeoResult.score?.overall ?? null,
    surfaceType: params.surfaceId ?? null,
  });

  // SHADOW-ONLY, default-OFF (GEOMETRY_EVAL_CAPTURE_ENABLED) content capture:
  // persist a REDACTED, adjudicable REFERENCE to the generated content at
  // geometry-decision time (salted hash + PII/secret-masked excerpt + signal-only
  // deep verdict + adjudicability metadata), NEVER raw content. Fire-and-forget,
  // write-only, and never throws into this response path — a byte-for-byte clone
  // of recordGeometryShadow's safety contract. Uses the SAME gravito_run_id as the
  // shadow write above → 1:1 join. MAIN PATH ONLY (the degraded path writes no
  // shadow row and is intentionally NOT captured). With the flag OFF this is a
  // no-op: zero writes, zero behavior change.
  recordGeometryEvalCapture({
    gravitoRunId: verdictView.gravito_run_id ?? null,
    surfaceType: params.surfaceId ?? null,
    productId: params.productId ?? null,
    content: generatedContent,
    liveVerdictDecision: verdictView.decision,
    deep: deepGeoResult,
    // FAIL-CLOSED gates: a row is written ONLY for an explicitly-eligible caller,
    // and the free-text excerpt ONLY for an explicitly excerpt-eligible caller.
    // No caller is flipped eligible in this packet.
    captureEligible: params.captureEligible === true,
    excerptEligible: params.excerptEligible === true,
    // Provenance — makes the row adjudicable (scores + structural issues) and
    // attributable (policy version, decision trace, actually-used model).
    geometryScore: deepGeoResult.score?.overall ?? null,
    liveVerdictScore: verdict.postAnalysis.score,
    policyVersion: verdict.gravitoInlineResult?.policy_version ?? null,
    decisionTraceId: verdict.gravitoInlineResult?.decision_trace_id ?? null,
    modelId: llmResult.model_used ?? llmResult.model ?? null,
    // Structural-only on write (description/suggestedFix dropped by the projector).
    liveVerdictIssues: verdict.postAnalysis.issues,
  });

  // ADVISORY repeat-failure recognition — a prior-memory READ, OFF the response
  // hot path, immediately after the capture WRITE above and using the SAME
  // gravito_run_id. Recognizes when this output matches a PRIOR PERSISTED FAILING
  // capture row (same salted content_hash + product, prior block/regenerate) and,
  // on recognition, emits increment-only telemetry + a content-free log. It NEVER
  // alters the verdict and NEVER blocks: fire-and-forget, fail-open, and a no-op
  // unless GEOMETRY_EVAL_CAPTURE_ENABLED is on. Does NOT touch the return object.
  recognizeRepeatFailure({
    content: generatedContent,
    productId: params.productId ?? null,
    surfaceType: params.surfaceId ?? null,
    gravitoRunId: verdictView.gravito_run_id ?? null,
  });

  // Step 8 (INFLUENCE): default-OFF, escalate-only geometry→verdict wiring
  // (packet gravito_behavior_wiring_proof_a). Behind
  // GEOMETRY_VERDICT_INFLUENCE_ENABLED a content-driven deep geometry `block`
  // ESCALATES the live verdict to `block` (via the canonical applyVerdict
  // safe-fallback). With the flag OFF this is a no-op: `influenced` is the exact
  // baseline {finalContent, verdict.decision, verdict.wasModified} and the
  // response below is byte-identical to today.
  const influenced = applyGeometryInfluence(
    llmResult,
    verdict,
    deepGeoResult,
    finalContent,
    auditTrail,
  );

  // Step 8 (RECALL INFLUENCE): default-OFF, escalate-only recall→verdict wiring
  // (packet gravito_recall_wiring_proof_a) — the RECALL half of remember →
  // recall → prevent, chained AFTER the geometry-influence seam. Behind
  // GEOMETRY_RECALL_INFLUENCE_ENABLED an in-path bounded recall READ recognizes
  // when THIS output matches a PRIOR PERSISTED FAILING verdict (same product +
  // salted content_hash, prior block/regenerate) and ESCALATES the (already
  // geometry-influenced) verdict to `block` via the canonical applyVerdict
  // safe-fallback. Escalate-only, product-scoped, fail-closed (null product /
  // null outcome → no escalation). With the flag OFF this is a no-op: NO DB read
  // runs and `recallInfluenced` is the exact `influenced` baseline, so the
  // response below is byte-identical to today.
  const recallInfluenced = await applyRecallInfluence(
    llmResult,
    verdict,
    influenced,
    {
      content: generatedContent,
      productId: params.productId ?? null,
      surfaceType: params.surfaceId ?? null,
      gravitoRunId: verdictView.gravito_run_id ?? null,
    },
    auditTrail,
  );

  // Step 8 (MANIFOLD INFLUENCE): default-OFF, escalate-only manifold→verdict
  // wiring (packet manifold_verdict_influence_proof_a) — the deep-math half of
  // the prevention spine, chained AFTER the recall-influence seam. Behind
  // MANIFOLD_VERDICT_INFLUENCE_ENABLED, when the accumulated per-session state
  // trajectory (from the default-OFF accumulator) classifies as a NON-DEGENERATE
  // UNSTABLE attractor, ESCALATE the (already content/recall-influenced) verdict
  // to `block` via the canonical applyVerdict safe-fallback. Escalate-only,
  // fail-closed (null session / degenerate trajectory → no escalation). With the
  // flag OFF this is a no-op: NO trajectory read runs and `manifoldInfluenced` is
  // the exact `recallInfluenced` baseline, so the response is byte-identical.
  const manifoldInfluenced = applyManifoldInfluence(
    llmResult,
    verdict,
    recallInfluenced,
    { sessionId: params.surfaceId || 'default' },
    auditTrail,
  );

  const baseResult = {
    content: manifoldInfluenced.content,
    governed: true,
    decision: manifoldInfluenced.decision,
    modified: manifoldInfluenced.modified,
    gravito_run_id: verdict.gravito_run_id,
    score: verdict.postAnalysis.score,
    issues: verdict.postAnalysis.issues.map(i => ({
      type: i.type,
      severity: i.severity,
      description: i.description,
    })),
    auditTrail,
    processingTimeMs: 0, // will be set by caller
    degradedMode: false,
    productRegistered: false, // will be set by caller
    rawResult: llmResult,
  };

  // Step 9 (CANONICAL RECEIPT): default-OFF, ADDITIVE canonical verdict receipt
  // (Gate→Remember→Compound→Earn-Authority) behind CANONICAL_VERDICT_RECEIPT_ENABLED.
  // Flag OFF ⇒ `baseResult` is returned UNCHANGED (same reference, no
  // `canonical_receipt` key) — byte-identical — and NOTHING is recorded. The
  // receipt is CONTENT-FREE (a salted hash only, never raw content) and DB-FREE.
  // ctx is best-effort: enforcementMode is NOT in scope here (it is computed as
  // cpMode in the outer governedGenerate) ⇒ null → 'unknown'. callerId is read
  // through the same widened view the control-plane gate uses
  // (GovernedGenerateParams does not declare it, but runtime callers may pass
  // it), falling back to productId. authenticatedTenant is the source-gated SEAM
  // for tenant safety: it is the ONLY input that can promote the receipt to
  // `authenticated_tenant`, and NO current caller populates it — so ctx.
  // authenticatedTenant is null and derivation binds `first_party_scope`
  // (productId present), BYTE-IDENTICAL to prior behavior.
  const callerIdView =
    (params as GovernedGenerateParams & { callerId?: string }).callerId ?? params.productId ?? null;
  return attachCanonicalReceiptIfEnabled(baseResult, verdict, {
    productId: params.productId ?? null,
    surfaceId: params.surfaceId ?? null,
    contentType: params.contentType ?? null,
    contentRole: params.contentRole ?? null,
    callerId: callerIdView,
    authenticatedTenant: params.authenticatedTenant ?? null,
    enforcementMode: null,
    modelProvider: null,
    modelId: llmResult.model_used ?? llmResult.model ?? null,
  });
}

// ============================================================================
// INTERNAL: Governance-Bypass Path (re-entrancy guard target)
// ============================================================================

/**
 * Serve a governedGenerate call that arrived INSIDE the LLM governance-bypass
 * context (i.e. an internal governance evaluation such as the prevention
 * layer's AI check). One plain safeLLM call, no re-governing — this is what
 * terminates the governedGenerate → co-processor → prevention layer →
 * governedGenerate recursion.
 */
async function generateInternalBypass(
  params: GovernedGenerateParams,
): Promise<GovernedGenerateResult> {
  const startTime = Date.now();
  const llmResult = await safeLLM(
    {
      messages: buildMessages(params),
      model: params.model,
      max_tokens: params.max_tokens,
      response_format: params.response_format,
      tools: params.tools,
      tool_choice: params.tool_choice,
    },
    { context: 'governed-generate:internal-bypass' },
  );
  return {
    content: extractContent(llmResult),
    governed: false,
    decision: 'pass',
    modified: false,
    score: 100,
    issues: [],
    auditTrail: ['[BYPASS] Internal governance evaluation — recursion guard; output not re-governed'],
    processingTimeMs: Date.now() - startTime,
    degradedMode: false,
    productRegistered: false,
    rawResult: llmResult,
  };
}

// ============================================================================
// INTERNAL: Degraded Mode Pipeline
// ============================================================================

async function generateDegradedMode(
  messages: InvokeParams['messages'],
  params: GovernedGenerateParams,
  auditTrail: string[],
): Promise<GovernedGenerateResult> {
  auditTrail.push(`[DEGRADED] Entering degraded mode pipeline.`);

  // Step 1: LLM generation (no governance wrapper). safeLLM never throws —
  // when every route is down it returns a structured degradation response,
  // which the local policy engine below still evaluates.
  const llmResult = await safeLLM(
    {
      messages,
      model: params.model,
      max_tokens: params.max_tokens,
      response_format: params.response_format,
      tools: params.tools,
      tool_choice: params.tool_choice,
    },
    { context: 'governed-generate:degraded' },
  );
  auditTrail.push(`[DEGRADED-LLM] Raw generation complete. Tokens: ${llmResult.usage?.completion_tokens ?? 0} completion / ${llmResult.usage?.total_tokens ?? 0} total${isFallbackResponse(llmResult) ? ' (fallback response)' : ''}.`);

  // Step 2: Score geometry on the degraded content (SHADOW MODE — observe only).
  // Mirrors the main-path pattern: enforceDegraded() returns a
  // GeometryEnforcementResult OBJECT, the response content stays the original
  // generated STRING (the prior `content = enforceDegraded(...)` leaked the
  // object as `content: string` — sibling of the shipped main-path fix).
  const degradedContent = extractContent(llmResult);
  const geoResult = enforceDegraded(degradedContent, unsafeCast(params, "boundary cast"));
  const content = selectShadowContent(degradedContent, geoResult);
  if (classifyEnforcementOutcome(geoResult) === 'enforced') {
    auditTrail.push(`[DEGRADED-GEOMETRY] Enforcement recorded (decision: ${geoResult.decision}).`);
  }
  recordGeometryEnforcement(geoResult, {
    productId: params.productId,
    surfaceId: params.surfaceId,
    contentType: params.contentType,
    degradedMode: true,
  });

  // Step 3: Evaluate with local policy engine
  const policyResult = evaluateDegradedPolicy({
    content,
    contentType: params.contentType || 'general',
    surfaceId: params.surfaceId,
    productId: params.productId,
    contentRole: params.contentRole,
    audienceType: params.audienceType,
  });
  auditTrail.push(`[DEGRADED-POLICY] Decision: ${policyResult.decision}, Score: ${policyResult.score}`);

  // Step 4: Record evaluation for later analysis (hash the CONTENT STRING for
  // the audit trail — the old call hashed the geometry object).
  auditTrail.push(`[DEGRADED-RECORD] contentHash: ${createHash('sha256').update(content).digest('hex').slice(0, 16)}…`);
  recordDegradedEvaluation(policyResult);

  // Step 5: Build final result
  return {
    content: policyResult.modifiedContent,
    governed: true, // It was governed, just by a degraded system
    decision: policyResult.decision,
    modified: policyResult.modifications.length > 0,
    score: policyResult.score,
    issues: policyResult.issues.map(i => ({
      type: i.type,
      severity: i.severity,
      description: i.description,
    })),
    auditTrail,
    processingTimeMs: 0,
    degradedMode: true,
    productRegistered: false,
    rawResult: llmResult,
  };
}

