/**
 * PR Audit Runs - Idempotent audit execution tracking
 * 
 * Idempotency key format: {repo}:{pr}:{sha}:{prompt_version}:{policy_version}
 * 
 * This table ensures:
 * 1. No duplicate audits for the same PR state
 * 2. Fast lookup of existing results
 * 3. Full audit trail for compliance
 */
export const prAuditRuns = pgTable("pr_audit_runs", {
  id: serial("id").primaryKey(),

  // Idempotency key (unique constraint)
  idempotencyKey: varchar("idempotencyKey", { length: 512 }).notNull().unique(),

  // Key components (for querying)
  repo: varchar("repo", { length: 255 }).notNull(), // e.g., "owner/repo"
  prNumber: integer("prNumber").notNull(),
  prSha: varchar("prSha", { length: 64 }).notNull(), // HEAD SHA at audit time
  promptVersion: varchar("promptVersion", { length: 32 }).notNull(), // e.g., "v1.2.0"
  policyVersion: varchar("policyVersion", { length: 32 }).notNull(), // e.g., "v1.0.0"

  // Run identification
  runId: varchar("runId", { length: 64 }).notNull().unique(),

  // Status
  status: varchar("status", { length: 50 }).default("pending").notNull(),

  // Model information (Claude + OpenAI + Gravito)
  primaryModel: varchar("primaryModel", { length: 64 }).notNull(), // e.g., "claude-3-5-sonnet-20241022"
  primaryProvider: varchar("primaryProvider", { length: 32 }).notNull(), // e.g., "anthropic"
  fallbackUsed: boolean("fallbackUsed").default(false).notNull(),
  fallbackModel: varchar("fallbackModel", { length: 64 }), // e.g., "gpt-4o"
  validationModel: varchar("validationModel", { length: 64 }), // e.g., "gravito-governance"

  // Audit results
  score: integer("score"), // 0-100
  passed: boolean("passed"),
  issuesCount: integer("issuesCount").default(0),
  criticalCount: integer("criticalCount").default(0),
  highCount: integer("highCount").default(0),
  mediumCount: integer("mediumCount").default(0),
  lowCount: integer("lowCount").default(0),

  // Validation results
  validationVerdict: varchar("validationVerdict", { length: 50 }),
  validationConfidence: decimal("validationConfidence", { precision: 5, scale: 4 }), // 0.0000 to 1.0000
  validationReasonCodes: text("validationReasonCodes"), // JSON array of reason codes

  // Files analyzed
  filesAnalyzed: text("filesAnalyzed"), // JSON array of file paths
  filesCount: integer("filesCount").default(0),

  // Full results (for cache retrieval)
  fullResult: text("fullResult"), // JSON: complete audit result object
  markdownSummary: text("markdownSummary"), // Human-readable summary

  // GitHub integration
  installationId: bigint("installationId", { mode: "number" }),
  commentId: bigint("commentId", { mode: "number" }), // GitHub comment ID where results were posted
  commentUrl: varchar("commentUrl", { length: 512 }),

  // Timing
  startedAt: timestamp("startedAt"),
  completedAt: timestamp("completedAt"),
  durationMs: integer("durationMs"), // Total execution time

  // Error handling
  errorCode: varchar("errorCode", { length: 64 }),
  errorMessage: text("errorMessage"),
  retryCount: integer("retryCount").default(0),

  // Metadata
  triggeredBy: varchar("triggeredBy", { length: 255 }), // GitHub username who triggered
  triggerType: varchar("triggerType", { length: 50 }).default("comment").notNull(),

  createdAt: timestamp("createdAt").defaultNow().notNull(),
  updatedAt: timestamp("updatedAt").defaultNow().notNull(),
}, (table) => [
  index("idx_pr_audit_runs_repo").on(table.repo),
  index("idx_pr_audit_runs_repo_createdAt").on(table.repo, table.createdAt),
]);
export type PrAuditRun = typeof prAuditRuns.$inferSelect;
export type InsertPrAuditRun = typeof prAuditRuns.$inferInsert;

/**
 * Helper to generate idempotency key
 */
export function generateIdempotencyKey(params: {
  repo: string;
  prNumber: number;
  prSha: string;
  promptVersion: string;
  policyVersion: string;
}): string {
  return `${params.repo}:${params.prNumber}:${params.prSha}:${params.promptVersion}:${params.policyVersion}`;
}


