/**
 * Product Entitlements — Per-product, per-org access control
 * 
 * Each row represents one "circuit" (product) that an org has access to.
 * Internal operator org has all circuits enabled.
 * External orgs only get circuits they've purchased.
 */
export const productEntitlements = pgTable("product_entitlements", {
  id: serial("id").primaryKey(),

  // Which org owns this entitlement
  orgId: integer("orgId").notNull(),

  // Which product circuit is entitled
  productCode: varchar("productCode", { length: 64 }).notNull(),

  // Is this circuit currently active?
  enabled: boolean("enabled").default(true).notNull(),

  // Per-product limits (overrides plan defaults if set)
  runsPerMonth: integer("runsPerMonth"),      // null = use plan default, -1 = unlimited
  runsPerMinute: integer("runsPerMinute"),     // null = use plan default, -1 = unlimited

  // Current usage (reset each billing period)
  runsUsedThisMonth: integer("runsUsedThisMonth").default(0).notNull(),

  // Source of entitlement
  source: varchar("source", { length: 50 }).default("plan").notNull(),

  // Timestamps
  createdAt: timestamp("createdAt").defaultNow().notNull(),
  updatedAt: timestamp("updatedAt").defaultNow().notNull(),
  expiresAt: timestamp("expiresAt"), // null = never expires
}, (table) => [
  // COMPOSITE UNIQUE: one entitlement row per (org, product) — the ON CONFLICT
  // target provisionEntitlements has always used. Name matches the index
  // APPLIED TO PROD on 2026-07-14 under operator go (see
  // scripts/db/product-entitlements-unique.sql) exactly, so drizzle-kit never
  // tries to re-create or rename it. Before it existed, every upsert failed
  // with 42P10 (8 errors per boot + Stripe-webhook entitlements never persisted).
  uniqueIndex("product_entitlements_org_product_unique").on(table.orgId, table.productCode),
]);
export type ProductEntitlement = typeof productEntitlements.$inferSelect;
export type InsertProductEntitlement = typeof productEntitlements.$inferInsert;

/**
 * Entitlement Denial Log — Records every denied access attempt
 */
export const entitlementDenials = pgTable("entitlement_denials", {
  id: serial("id").primaryKey(),

  // Who was denied
  orgId: integer("orgId").notNull(),
  apiKeyPrefix: varchar("apiKeyPrefix", { length: 12 }),

  // What was denied
  productCode: varchar("productCode", { length: 64 }).notNull(),
  toolName: varchar("toolName", { length: 128 }),

  // Why
  reason: varchar("reason", { length: 64, enum: [
    "not_entitled",
    "disabled",
    "expired",
    "rate_limited",
    "budget_exceeded",
  ] as const }).notNull(),

  // Context
  requestIp: varchar("requestIp", { length: 45 }),

  createdAt: timestamp("createdAt").defaultNow().notNull(),
});
export type EntitlementDenial = typeof entitlementDenials.$inferSelect;
export type InsertEntitlementDenial = typeof entitlementDenials.$inferInsert;


/**
 * Dogfood configuration — persistent per-user dogfood mode state.
 * Survives server restarts. One row per user who has toggled dogfood.
 */
export const dogfoodConfig = pgTable("dogfood_config", {
  id: serial("id").primaryKey(),
  userId: integer("userId").notNull().unique(),
  /** null = dogfood off (use internal tenant), 'free'|'starter'|'growth'|'enterprise' = simulated plan */
  simulatedPlan: varchar("simulatedPlan", { length: 32 }),
  /** The simulated org ID (cached for fast lookups) */
  simulatedOrgId: integer("simulatedOrgId"),
  createdAt: timestamp("createdAt").defaultNow().notNull(),
  updatedAt: timestamp("updatedAt").defaultNow().notNull(),
});
export type DogfoodConfig = typeof dogfoodConfig.$inferSelect;
