/**
 * Content Integrity Score History — Longitudinal Trend Tracking
 * 
 * Stores periodic snapshots of the unified Content Integrity Score (0-100)
 * and per-domain breakdowns. Enables:
 * 1. Sparkline trend charts in the Control Tower
 * 2. Week-over-week improvement/decline tracking
 * 3. Historical proof that governance is improving over time
 * 4. Executive reporting with trend data
 * 
 * Recorded on each watchdog cycle (every ~60s) and on-demand scans.
 * 
 * Created: Feb 9, 2026
 * Phase: Operational Proof — Trend Tracking
 */
export const integrityScoreHistory = pgTable("integrity_score_history", {
  id: serial("id").primaryKey(),

  // Snapshot identification
  snapshotId: varchar("snapshotId", { length: 64 }).notNull().unique(),

  // The single metric
  overallScore: integer("overallScore").notNull(), // 0-100
  status: varchar("status", { length: 16 }).notNull(), // healthy/degraded/critical
  trend: varchar("trend", { length: 16 }).notNull(), // improving/stable/declining

  // Per-domain scores (JSON for flexibility as domains may evolve)
  domainScores: json("domainScores").$type<Record<string, number>>(), // { truth: 85, compliance: 90, ... }

  // Aggregate metrics
  activeDomains: integer("activeDomains").notNull(),
  unknownDomains: integer("unknownDomains").notNull(),
  totalViolations: integer("totalViolations").default(0).notNull(),

  // Delta tracking
  previousScore: integer("previousScore"), // For sparkline delta
  scoreDelta: integer("scoreDelta"), // +/- points from previous
  weekOverWeekDelta: integer("weekOverWeekDelta"), // +/- points from 7 days ago

  // Source context
  source: varchar("source", { length: 32 }).default("watchdog").notNull(), // watchdog, manual, scan

  capturedAt: timestamp("capturedAt").defaultNow().notNull(),
});
export type IntegrityScoreSnapshot = typeof integrityScoreHistory.$inferSelect;
export type InsertIntegrityScoreSnapshot = typeof integrityScoreHistory.$inferInsert;

